task.vi:
Cho biết kết quả hiển thị ra màn hình của hai chương trình sau:
(a)
#include <iostream>
using namespace std;

void m(int x, int y[])
{
  x = 3;
  y[0] = 3;
}

int main()
{
  int number = 0;
  int numbers[1];

  m(number, numbers);

  cout << "number is " << number
    << " and numbers[0] is " << numbers[0];

  return 0;
}

(b)
#include <iostream>
using namespace std;

void reverse(int list[], int size)
{
  for (int i = 0; i < size / 2; i++)
  {
    int temp = list[i];
    list[i] = list[size - 1 - i];
    list[size - 1 - i] = temp;
  }
}

int main()
{
  int list[] = {1, 2, 3, 4, 5};
  int size = 5;
  reverse(list, size);
  for (int i = 0; i < size; i++)
    cout << list[i] << " ";

  return 0;
}

