task.vi:
Giả sử đoạn mã sau đây được viết để đảo ngược các ký tự trong một chuỗi, hãy giải thích tại sao đoạn mã bị sai:
string s = "ABCD";
for (int i = 0, j = s.size() - 1; i < s.size(); i++, j--)
{
  // Swap s[i] with s[j]
  char temp = s[i];
  s[i] = s[j];
  s[j] = temp;
}

cout << "The reversed string is " << s << endl;

