#include <iostream>

void reverseCopy(const int source[], int target[], int size) {
    for (int i = 0, j = size - 1; i < size; ++i, --j) {
        target[j] = source[i];
    }
}

void printArray(const int list[], int size) {
    for (int i = 0; i < size; ++i) {
        std::cout << list[i] << (i + 1 < size ? " " : "");
    }
    std::cout << "\n";
}

int main() {
    const int SIZE = 6;
    int list[SIZE] = {1, 2, 3, 4, 5, 6};
    int reversedList[SIZE];

    reverseCopy(list, reversedList, SIZE);

    std::cout << "Original: ";
    printArray(list, SIZE);
    std::cout << "Reversed: ";
    printArray(reversedList, SIZE);

    return 0;
}

#include <iostream>

const int NUM_LETTERS = 26;

void countLetters(const char text[], int length, int counts[]) {
    for (int i = 0; i < NUM_LETTERS; ++i) {
        counts[i] = 0;
    }
    for (int i = 0; i < length; ++i) {
        char ch = text[i];
        if (ch >= 'a' && ch <= 'z') {
            counts[ch - 'a']++;
        }
    }
}

void displayCounts(const int counts[]) {
    for (int i = 0; i < NUM_LETTERS; ++i) {
        if (counts[i] > 0) {
            std::cout << static_cast<char>(i + 'a') << ": " << counts[i] << "\n";
        }
    }
}

int main() {
    const char sample[] = "abacaba";
    const int len = sizeof(sample) - 1; // exclude null terminator
    int counts[NUM_LETTERS];

    countLetters(sample, len, counts);
    displayCounts(counts);

    return 0;
}
